-- This script was generated by the ERD tool in pgAdmin 4, then reviewed against
-- the actual query patterns in RecipeRepository / UserRepository / SessionRepository
-- and adjusted: added missing FK, missing indexes, pg_trgm extension for search,
-- and removed indexes that duplicated an existing primary key index.
--
-- This file is fed directly to jOOQ's DDLDatabase codegen (build.gradle.kts) -
-- it holds only structural DDL (extension, schemas, tables, columns/types, FK
-- constraints). Indexes have no bearing on the generated Kotlin classes, so
-- all of them (not just the one jOOQ's parser can't handle) live in
-- db/indexes.sql instead, applied separately after this file.
--
-- No BEGIN/COMMIT wrapper here on purpose - jOOQ's DDLDatabase parses
-- individual DDL statements and doesn't understand psql transaction-control
-- commands. Apply atomically with `psql -1 -f db/schema.sql` if that matters.

-- required for the `%` similarity operator and similarity() used by
-- RecipeRepository.selectRecipesWithFilters() (fuzzy recipe name search)
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- named app_auth (not auth) because Supabase reserves the `auth` schema for
-- its own built-in authentication system
CREATE SCHEMA IF NOT EXISTS app_auth;

CREATE TABLE IF NOT EXISTS app_auth.sessions
(
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL,
    session_hash character varying(64) COLLATE pg_catalog."default" NOT NULL,
    created_at timestamp with time zone NOT NULL DEFAULT now(),
    expires_at timestamp with time zone NOT NULL DEFAULT (now() + INTERVAL '30' DAY),
    last_used_at timestamp with time zone NOT NULL DEFAULT now(),
    revoked boolean NOT NULL DEFAULT false,
    CONSTRAINT sessions_pkey PRIMARY KEY (id),
    CONSTRAINT sessions_hash_key UNIQUE (session_hash)
);

CREATE TABLE IF NOT EXISTS app_auth.users
(
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    -- nullable: a Google (or other future OAuth provider) account has nothing
    -- to hash here - see app_auth.oauth_identities below and
    -- AuthService.login()'s null-password guard, which stops a password
    -- login attempt against an account like that. Every password-registered
    -- account still always has one; this only relaxes the *column*.
    password character varying(255) COLLATE pg_catalog."default",
    username character varying(100) COLLATE pg_catalog."default" NOT NULL,
    email character varying(100) COLLATE pg_catalog."default",
    email_verified boolean NOT NULL DEFAULT false,
    -- set when the user requests account deletion (UserService.requestAccountDeletion),
    -- cleared if they cancel before the grace period ends (UserService.cancelAccountDeletion).
    -- Null means "not scheduled for deletion". A daily job
    -- (AccountDeletionService.purgeExpiredAccounts) hard-deletes any account whose
    -- value here is more than 30 days in the past - see that class for why this is a
    -- flag-on-the-row rather than a separate archive table.
    deletion_requested_at timestamp with time zone,
    CONSTRAINT users_pkey PRIMARY KEY (id),
    CONSTRAINT users_email_key UNIQUE (email)
);

-- Links a third-party OAuth/OIDC identity (currently just Google) to one
-- app_auth.users row. Kept as its own table rather than a "google_subject"
-- column on users so a user can later have more than one linked provider,
-- and so linking a provider onto an *existing* password account (see
-- GoogleAuthService.resolveOrCreateUser - matched by verified email) never
-- requires touching the users row itself.
CREATE TABLE IF NOT EXISTS app_auth.oauth_identities
(
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL,
    -- e.g. "google" - a free-text discriminator rather than an enum so a
    -- future provider is just a new value, no schema change
    provider character varying(20) COLLATE pg_catalog."default" NOT NULL,
    -- the provider's own stable user id (Google's OIDC "sub" claim) - never
    -- the email, which a provider account can change
    provider_subject character varying(255) COLLATE pg_catalog."default" NOT NULL,
    created_at timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT oauth_identities_pkey PRIMARY KEY (id),
    CONSTRAINT oauth_identities_provider_subject_key UNIQUE (provider, provider_subject)
);

CREATE TABLE IF NOT EXISTS app_auth.email_verification_tokens
(
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL,
    token_hash character varying(64) COLLATE pg_catalog."default" NOT NULL,
    created_at timestamp with time zone NOT NULL DEFAULT now(),
    expires_at timestamp with time zone NOT NULL DEFAULT (now() + INTERVAL '24' HOUR),
    used_at timestamp with time zone,
    CONSTRAINT email_verification_tokens_pkey PRIMARY KEY (id),
    CONSTRAINT email_verification_tokens_hash_key UNIQUE (token_hash)
);

-- Same shape and purpose as app_auth.email_verification_tokens, just for the
-- "forgot password" flow instead of registration - see PasswordResetService,
-- which mirrors EmailVerificationService's workflow against this table.
CREATE TABLE IF NOT EXISTS app_auth.password_reset_tokens
(
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL,
    token_hash character varying(64) COLLATE pg_catalog."default" NOT NULL,
    created_at timestamp with time zone NOT NULL DEFAULT now(),
    expires_at timestamp with time zone NOT NULL DEFAULT (now() + INTERVAL '1' HOUR),
    used_at timestamp with time zone,
    CONSTRAINT password_reset_tokens_pkey PRIMARY KEY (id),
    CONSTRAINT password_reset_tokens_hash_key UNIQUE (token_hash)
);

CREATE TABLE IF NOT EXISTS public.hero_images
(
    image_id uuid NOT NULL DEFAULT gen_random_uuid(),
    index integer NOT NULL,
    recipe_id uuid NOT NULL,
    CONSTRAINT hero_images_pkey PRIMARY KEY (image_id),
    CONSTRAINT hero_images_recipe_id_index_key UNIQUE (recipe_id, index)
);

CREATE TABLE IF NOT EXISTS public.images
(
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    url text COLLATE pg_catalog."default" NOT NULL,
    CONSTRAINT images_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS public.ingredients
(
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    name character varying(50) COLLATE pg_catalog."default" NOT NULL,
    index integer NOT NULL,
    amount numeric(6, 2) NOT NULL,
    measuring_unit character varying(20) COLLATE pg_catalog."default" NOT NULL,
    recipe_id uuid NOT NULL,
    CONSTRAINT ingredients_pkey PRIMARY KEY (id),
    CONSTRAINT ingredients_recipe_id_index_key UNIQUE (recipe_id, index)
);

CREATE TABLE IF NOT EXISTS public.instruction_images
(
    image_id uuid NOT NULL DEFAULT gen_random_uuid(),
    index integer NOT NULL,
    instruction_id uuid NOT NULL,
    CONSTRAINT instruction_images_pkey PRIMARY KEY (image_id),
    CONSTRAINT instruction_images_instruction_id_index_key UNIQUE (instruction_id, index)
);

CREATE TABLE IF NOT EXISTS public.instructions
(
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    index integer NOT NULL,
    instruction text COLLATE pg_catalog."default" NOT NULL,
    recipe_id uuid NOT NULL,
    CONSTRAINT instructions_pkey PRIMARY KEY (id),
    CONSTRAINT instructions_recipe_id_index_key UNIQUE (recipe_id, index)
);

CREATE TABLE IF NOT EXISTS public.recipes
(
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    name character varying(255) COLLATE pg_catalog."default" NOT NULL,
    description character varying COLLATE pg_catalog."default" NOT NULL,
    cook_time character varying(50) COLLATE pg_catalog."default" NOT NULL,
    side_notes character varying COLLATE pg_catalog."default",
    difficulty integer NOT NULL,
    portions integer NOT NULL,
    likes bigint NOT NULL DEFAULT 0,
    created_date date NOT NULL DEFAULT CURRENT_DATE,
    user_id uuid NOT NULL,
    user_name character varying(100) COLLATE pg_catalog."default" NOT NULL,
    -- true excludes this recipe from the global feed/search (RecipeRepository.
    -- searchConditions with excludePrivate=true) and blocks GET /recipe/{id} for
    -- anyone but the owner (RecipeService.findRecipeById) - toggled from the
    -- dashboard (PATCH /recipe/{id}/private), never from the recipe editor itself.
    is_private boolean NOT NULL DEFAULT false,
    CONSTRAINT recipes_pkey PRIMARY KEY (id),
    CONSTRAINT recipes_difficulty_check CHECK (difficulty >= 1 AND difficulty <= 5)
);

-- Tracks which user liked which recipe - a composite PK (rather than a
-- surrogate id) both prevents a user from liking the same recipe twice at
-- the DB level (a second INSERT for the same pair violates the PK) and
-- doubles as the index RecipeRepository.hasUserLikedRecipe()/likeRecipe()
-- need to check "did this user already like this recipe" in one lookup.
-- recipes.likes above stays a separately-maintained counter (incremented/
-- decremented alongside inserts/deletes here, see RecipeService.likeRecipe/
-- unlikeRecipe) rather than being derived with COUNT(*) on every read.
CREATE TABLE IF NOT EXISTS public.recipe_likes
(
    recipe_id uuid NOT NULL,
    user_id uuid NOT NULL,
    created_at timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT recipe_likes_pkey PRIMARY KEY (recipe_id, user_id)
);

-- MATCH SIMPLE is Postgres's default FK matching behavior when omitted -
-- dropped here (vs. what pgAdmin's ERD tool emits) purely because jOOQ's
-- DDLDatabase parser doesn't recognize the MATCH clause; no functional change.

ALTER TABLE IF EXISTS app_auth.sessions
    ADD CONSTRAINT sessions_user_id_fkey FOREIGN KEY (user_id)
    REFERENCES app_auth.users (id)
    ON UPDATE NO ACTION
    ON DELETE CASCADE;

ALTER TABLE IF EXISTS app_auth.email_verification_tokens
    ADD CONSTRAINT email_verification_tokens_user_id_fkey FOREIGN KEY (user_id)
    REFERENCES app_auth.users (id)
    ON UPDATE NO ACTION
    ON DELETE CASCADE;

ALTER TABLE IF EXISTS app_auth.oauth_identities
    ADD CONSTRAINT oauth_identities_user_id_fkey FOREIGN KEY (user_id)
    REFERENCES app_auth.users (id)
    ON UPDATE NO ACTION
    ON DELETE CASCADE;

ALTER TABLE IF EXISTS app_auth.password_reset_tokens
    ADD CONSTRAINT password_reset_tokens_user_id_fkey FOREIGN KEY (user_id)
    REFERENCES app_auth.users (id)
    ON UPDATE NO ACTION
    ON DELETE CASCADE;

ALTER TABLE IF EXISTS public.hero_images
    ADD CONSTRAINT hero_images_image_id_fkey FOREIGN KEY (image_id)
    REFERENCES public.images (id)
    ON UPDATE NO ACTION
    ON DELETE CASCADE;

ALTER TABLE IF EXISTS public.hero_images
    ADD CONSTRAINT hero_images_recipe_id_fkey FOREIGN KEY (recipe_id)
    REFERENCES public.recipes (id)
    ON UPDATE NO ACTION
    ON DELETE CASCADE;

ALTER TABLE IF EXISTS public.ingredients
    ADD CONSTRAINT ingredients_recipe_id_fkey FOREIGN KEY (recipe_id)
    REFERENCES public.recipes (id)
    ON UPDATE NO ACTION
    ON DELETE CASCADE;

ALTER TABLE IF EXISTS public.instruction_images
    ADD CONSTRAINT instruction_images_image_id_fkey FOREIGN KEY (image_id)
    REFERENCES public.images (id)
    ON UPDATE NO ACTION
    ON DELETE CASCADE;

ALTER TABLE IF EXISTS public.instruction_images
    ADD CONSTRAINT instruction_images_instruction_id_fkey FOREIGN KEY (instruction_id)
    REFERENCES public.instructions (id)
    ON UPDATE NO ACTION
    ON DELETE CASCADE;

ALTER TABLE IF EXISTS public.instructions
    ADD CONSTRAINT instructions_recipe_id_fkey FOREIGN KEY (recipe_id)
    REFERENCES public.recipes (id)
    ON UPDATE NO ACTION
    ON DELETE CASCADE;

ALTER TABLE IF EXISTS public.recipes
    ADD CONSTRAINT recipes_user_id_fkey FOREIGN KEY (user_id)
    REFERENCES app_auth.users (id)
    ON UPDATE NO ACTION
    ON DELETE CASCADE;

ALTER TABLE IF EXISTS public.recipe_likes
    ADD CONSTRAINT recipe_likes_recipe_id_fkey FOREIGN KEY (recipe_id)
    REFERENCES public.recipes (id)
    ON UPDATE NO ACTION
    ON DELETE CASCADE;

ALTER TABLE IF EXISTS public.recipe_likes
    ADD CONSTRAINT recipe_likes_user_id_fkey FOREIGN KEY (user_id)
    REFERENCES app_auth.users (id)
    ON UPDATE NO ACTION
    ON DELETE CASCADE;
